---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// OTP field: A one-time code, one box per digit, that fills from a paste.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change otp-field.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './otp-field.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="otp-field" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="otp panel">
  <span class="otp-ic"><svg class="i s"><use href="#i-mail"/></svg></span>
  <b class="otp-t">Check your email</b>
  <p class="muted otp-s">Enter the 6-digit code we sent to maya@designme.studio</p>
  <div class="otp-in" role="group" aria-label="Verification code"></div>
  <p class="otp-m" aria-live="polite"></p>
  <p class="muted otp-f"><span class="otp-rs">Resend code in <span class="num">0:30</span></span></p>
</div>
  </Fragment></div>
</div>
<script>
  import './otp-field.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- OTP field ---------- */
/* a one-time code, one box per digit: typing moves along, Backspace moves back, and a paste fills every box. A wrong
   code shakes and turns red; typing again starts it over */
.otp{position:relative;width:100%;max-width:360px;margin:0 auto;padding:22px var(--dm-s-5) 18px;display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center}
.otp-ic{width:40px;height:40px;border-radius:var(--dm-r-in);background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;margin-bottom:6px}
.otp-t{font-weight:500;font-size:14px}
.otp-s{margin:0 0 10px;font-size:13px;line-height:1.45;max-width:260px}
.otp-in{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;max-width:286px}
.otp-in .sep{flex:none;width:8px;height:1.5px;border-radius:1px;background:var(--dm-rail);margin:0 2px}
.otp-d{flex:1 1 0;min-width:0;max-width:40px;height:var(--dm-field-h);padding:0;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);text-align:center;font:inherit;font-size:14px;font-weight:500;font-variant-numeric:tabular-nums;color:var(--dm-fg);caret-color:var(--dm-accent-mark,var(--dm-accent));transition:box-shadow .25s,background .25s,color .25s,transform .25s var(--dm-ease)}
@supports (corner-shape:squircle){.otp-d{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.otp-d:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* (not .pop, which is the shared popover class and would hide the box) */
.otp-d.bump{transform:scale(1.06)}
.otp-in.vf .otp-d{color:var(--dm-fg2)}
/* a wrong code keeps its red edge, focused or not, until typing starts it over */
.otp-in.bad .otp-d{background:var(--dm-bad-bg);color:var(--dm-bad);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-bad) 55%,transparent)}
.otp-in.bad{animation:otpsh .42s}
@keyframes otpsh{20%{transform:translateX(-6px)}40%{transform:translateX(5px)}60%{transform:translateX(-3px)}80%{transform:translateX(2px)}}
.otp-in.ok .otp-d{background:var(--dm-ok-bg);color:var(--dm-ok);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-ok) 35%,transparent)}
.otp-m{margin:var(--dm-s-2) 0 0;min-height:20px;display:inline-flex;align-items:center;justify-content:center;gap:6px;font-size:12.5px;color:var(--dm-fg2)}
.otp-m .spin{width:11px;height:11px}
.otp-m.bad{color:var(--dm-bad)}
.otp-m.ok{color:var(--dm-ok)}
.otp-f{margin:2px 0 0;font-size:12.5px}
.otp-f button{color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;font-size:12.5px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter } from '../core/core.js';
DM.def('otp-field', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{mail}', I('mail'));
  const CODE = '482157';
  const box = $('.otp-in', r), msg = $('.otp-m', r), rs = $('.otp-rs', r);
  // one box per digit, with a short dash between the two halves. The first box carries autocomplete="one-time-code",
  // so a phone can offer the code from a message
  box.innerHTML = Array.from({ length:6 }, (_, i) => `${i === 3 ? '<span class="sep" aria-hidden="true"></span>' : ''}<input class="otp-d" inputmode="numeric" pattern="[0-9]*" maxlength="1" autocomplete="${i ? 'off' : 'one-time-code'}" aria-label="Digit ${i + 1} of 6">`).join('');
  const ins = $$('.otp-d', box);
  let state = 'idle', tries = 3;
  const say = (h, cls) => { msg.className = 'otp-m' + (cls ? ' ' + cls : ''); msg.innerHTML = h; if (h) enter(msg); };
  const code = () => ins.map(i => i.value).join('');
  const pop = el => { el.classList.add('bump'); c.later(160, () => el.classList.remove('bump')); };
  // a wrong code stays red until you type again, which starts it over
  function fresh(){ if (state !== 'bad') return; state = 'idle'; box.classList.remove('bad'); ins.forEach(i => { i.value = ''; i.removeAttribute('aria-invalid'); }); say(''); }
  function put(i, d){ fresh(); ins[i].value = d; pop(ins[i]); if (code().length === 6) verify(); }
  // the code is checked as soon as the last box is filled
  function verify(){
    if (state !== 'idle') return; state = 'vf';
    c.run(async () => {
      box.classList.add('vf'); ins.forEach(i => { i.readOnly = true; i.blur(); }); say('<span class="spin"></span>Checking the code');
      await c.wait(900); box.classList.remove('vf'); ins.forEach(i => i.readOnly = false);
      if (code() === CODE){
        state = 'ok'; box.classList.add('ok'); ins.forEach(i => i.readOnly = true);
        say(`${I('ok','xs')}Email verified`, 'ok'); rs.parentElement.hidden = true; return;
      }
      state = 'bad'; tries--; box.classList.remove('bad'); void box.offsetWidth; box.classList.add('bad'); ins.forEach(i => i.setAttribute('aria-invalid', 'true'));
      say(`${I('alert','xs')}That code doesn't match. ${tries ? `${tries} ${tries === 1 ? 'try' : 'tries'} left` : 'Send a new code to try again'}`, 'bad');
    });
  }
  // typing a digit fills the box and moves on; Backspace clears it, or the one before; the arrows move; a paste fills
  // every box from the first
  ins.forEach((inp, i) => {
    inp.oninput = () => { const d = inp.value.replace(/\D/g, ''); inp.value = ''; if (!d) return; if (d.length > 1) return fill(d); put(i, d); if (ins[i + 1] && state === 'idle') ins[i + 1].focus(); };
    inp.onkeydown = e => {
      if (e.key === 'Backspace'){ e.preventDefault(); if (state === 'bad'){ fresh(); ins[0].focus(); } else if (inp.value){ inp.value = ''; } else if (ins[i - 1]){ ins[i - 1].value = ''; ins[i - 1].focus(); } }
      else if (e.key === 'ArrowLeft' && ins[i - 1]){ e.preventDefault(); ins[i - 1].focus(); }
      else if (e.key === 'ArrowRight' && ins[i + 1]){ e.preventDefault(); ins[i + 1].focus(); }
      else if (/^\d$/.test(e.key) && inp.value){ e.preventDefault(); const j = state === 'bad' ? 0 : i; put(j, e.key); if (ins[j + 1] && state === 'idle') ins[j + 1].focus(); }
    };
    inp.onpaste = e => { e.preventDefault(); fill((e.clipboardData || window.clipboardData).getData('text')); };
    inp.onfocus = () => inp.select();
  });
  function fill(text, focus = true){
    const d = text.replace(/\D/g, '').slice(0, 6); if (!d) return;
    fresh(); ins.forEach((inp, i) => { inp.value = d[i] || ''; if (d[i]) c.later(i * 40, () => pop(inp)); });
    if (d.length === 6) verify(); else if (focus) ins[d.length].focus();
  }
  // the resend link waits thirty seconds
  let left = 30; const ns = $('.num', rs);
  const iv = c.every(1000, () => { if (state === 'ok') return clearInterval(iv); left--; ns.textContent = '0:' + String(left).padStart(2, '0'); if (left <= 0){ clearInterval(iv); rs.innerHTML = '<button>Resend code</button>'; $('button', rs).onclick = () => { rs.textContent = 'A new code is on its way'; }; } });
  // the preview's story: paste a code with two digits swapped, see it fail, and type the right one
  c.story(async s => {
    await s.beat(3);
    await s.tap(ins[0]); s.away();
    await s.beat(1); fill('482175', false);
    await s.until(() => state === 'bad'); await s.beat(4);
    for (let i = 0; i < 6; i++){ put(i, CODE[i]); await s.beat(1); }
    await s.until(() => state === 'ok'); await s.beat(2);
  });
});
